  "Segment comparisons use the verified record and the average of the fastest published efforts. The benchmark updates as more results are published.": "Usporedbe dionica koriste potvrđeni rekord i prosjek najbržih objavljenih vremena. Rekord se ažurira s objavom novih rezultata.",
