  "Compare effort by section": "Usporedi vrijeme prema dionici",
  "This is the visual comparison layer of the page. Use it to see where the verified record pulls away, where the field average stays close, and which sections decide the route.": "Ovo je vizualni usporedni prikaz stranice. Pokazuje gdje potvrđeni rekord stvara prednost, gdje je prosjek polja blizu i koje dionice odlučuju rutu.",
