  "This page holds the visual and social layer of the route: route photos, user submissions, scenic highlights, seasonal condition cues, and the review feedback that helps runners judge fit before they commit.": "Ova stranica okuplja vizualni i društveni sloj rute: fotografije, sadržaj korisnika, slikovite dijelove, sezonske uvjete i recenzije koje natjecateljima pomažu procijeniti odgovara li im ruta.",
