  "Places 1–100 receive graded points. Every official finisher from 101st onward receives 2 participation points.": "Mjesta 1.–100. dobivaju stupnjevane bodove. Svaki službeni finišer od 101. mjesta nadalje dobiva 2 boda za sudjelovanje.",
  "Places 1–20 receive graded points. Every official finisher from 21st onward receives 10 participation points.": "Mjesta 1.–20. dobivaju stupnjevane bodove. Svaki službeni finišer od 21. mjesta nadalje dobiva 10 bodova za sudjelovanje.",
  "Places 1–50 receive graded points. Every official finisher from 51st onward receives 5 participation points.": "Mjesta 1.–50. dobivaju stupnjevane bodove. Svaki službeni finišer od 51. mjesta nadalje dobiva 5 bodova za sudjelovanje.",
  "Plan final standings freeze, awards and prize lists, team trophies, sponsor recap, media pack, and archived reference material for next season.": "Planiraj zaključavanje završnog poretka, nagrade i popise dobitnika, ekipne trofeje, izvješće za sponzore, medijski paket i arhivsku građu za sljedeću sezonu.",
  "Plan two competition ladders under one league identity. Each round race can later map one short and one long race into the matching cup.": "Planiraj dva poretka natjecanja unutar jedne lige. Svako kolo može naknadno povezati jednu kratku i jednu dugu utrku s odgovarajućim kupom.",
  "Planned Rounds": "Planirana kola",
