  "Points never cross between these tables. Athletes and clubs can rank differently in every race category.": "Bodovi se ne prenose između ovih tablica. Natjecatelji i klubovi mogu imati različit poredak u svakoj kategoriji utrke.",
  "Points standings": "Bodovni poredak",
  "Pool club scores from every mapped race in the round and count four, rewarding deeper rosters.": "Objedini klupske bodove iz svake povezane utrke u kolu i računaj četiri rezultata, čime se nagrađuju brojnije ekipe.",
  "Pool the club's Short and Long results into one overall round score, then sum its strongest three performances. Clubs do not compete in separate race or age categories.": "Objedini klupske rezultate kratke i duge utrke u jedan ukupni rezultat kola, a zatim zbroji tri najbolja rezultata. Klubovi se ne natječu u odvojenim utrkama ili dobnim kategorijama.",
