  "Set team and club scoring rules, number of counting athletes, mixed-team requirements, transfers, reserve scorers, and how team penalties or exclusions are handled.": "Postavi pravila ekipnog i klupskog bodovanja, broj natjecatelja koji se boduju, uvjete mješovitih ekipa, prelaske, rezerve te postupanje s ekipnim kaznama ili isključenjima.",
