  "Start with identity and scoring. Race editions and race mappings come after the private season shell exists.": "Unesi naziv i pravila bodovanja. Kad spremiš nacrt sezone, možeš dodati kola i povezati utrke.",
  "Start with one season table. Race editions become rounds first, then one scored race from each race feeds the Overall competition.": "Započni jednom tablicom sezone. Izdanja utrke prvo postaju kola, a zatim jedna bodovana utrka iz svakog utrke ulazi u ukupno natjecanje.",
