  "Test Race accepts up to 10 athletes. The athlete remains unassigned until a bib is entered at the desk.": "Probna utrka prihvaća do 10 natjecatelja. Natjecatelj ostaje neraspoređen dok se na pultu ne unese startni broj.",
  "Test Race workflow": "Postupak probne utrke",
  "Test punches captured, replayed, and reconciled": "Probni prolazi su zabilježeni, ponovljeni i usklađeni",
  "Test registration added. Continue in Desk & check-in when the athlete arrives.": "Probna prijava je dodana. Kad natjecatelj stigne, otvori odjeljak Dolazak i brojevi.",
  "The closed-registration snapshot is the exact operational roster used by check-in and timing. Close or reopen registrations from Desk &amp; check-in.": "Zaključana startna lista koristi se za potvrdu dolaska i mjerenje vremena. Prijave možeš zatvoriti ili ponovno otvoriti u odjeljku Dolazak i brojevi.",
  "The closed-registration snapshot is the exact operational roster used by check-in and timing. Close or reopen registrations from Desk & check-in.": "Zaključana startna lista koristi se za potvrdu dolaska i mjerenje vremena. Prijave možeš zatvoriti ili ponovno otvoriti u odjeljku Dolazak i brojevi.",
  "The entries remain on this device. Keep this page open and try Sync again when the connection is stable.": "Unosi su i dalje na ovom uređaju. Ne zatvaraj stranicu. Kad se veza vrati, ponovno odaberi slanje unosa.",
  "The official start time is saved automatically when the countdown reaches zero.": "Službeno vrijeme starta automatski se sprema kada odbrojavanje dosegne nulu.",
  "The picture preview appears immediately. You can edit every field later.": "Pregled slike prikazuje se odmah. Sva polja možeš urediti poslije.",
  "There is no setup wizard after this form. The organization dashboard keeps the structure visible.": "Nakon spremanja sve podatke možeš urediti u pregledu organizacije.",
  "This cannot be undone from the organizer workspace and it does not refund paid registrations. Payment, cancellation, communication, and race-day audit records will remain retained.": "Ovo se ne može poništiti iz organizatorskog prostora i ne vraća novac za plaćene prijave. Zapisi o plaćanju, otkazivanju, komunikaciji i danu utrke ostat će sačuvani.",
  "This creates an immutable start race": "Start će biti trajno zabilježen",
  "This organization becomes the default team for new races, leagues, and routes. If you join another organization later, switch the default from Organization & Team.": "Ova organizacija postaje zadana ekipa za nove utrke, lige i rute. Ako se poslije pridružiš drugoj organizaciji, promijeni zadanu u odjeljku Organizacija i ekipa.",
  "This payment went directly to the organizer bank account. Issue any refund from that account; automated provider refunds do not apply to this transfer.": "Ova je uplata izravno sjela na bankovni račun organizatora. Svaki povrat izvrši s tog računa; automatski povrati pružatelja ne primjenjuju se na ovu uplatu.",
  "This permanently deletes only the organization workspace and cannot be undone. Any separate club, including one with the same name, remains unchanged. Type the exact organization name to continue.": "Organizacija će biti trajno izbrisana. To ne možeš poništiti. Zasebni klubovi ostaju, čak i ako imaju isto ime. Za nastavak upiši točan naziv organizacije.",
  "This race has no configured checkpoints.": "Ova utrka nema postavljene kontrolne točke.",
  "This releases the race place and records the reason. Payment refunds remain a separate finance action.": "Time se oslobađa mjesto u utrci i bilježi razlog. Povrat uplate ostaje zasebna financijska radnja.",
  "This removes all": "Time se uklanjaju sve",
