  "Validate first, inspect every rejected row, then commit once. Imported athletes remain claimable and organizer consent attestation is recorded separately.": "Najprije provjeri, pregledaj svaki odbijeni redak, a zatim jednom potvrdi uvoz. Uvezeni natjecatelji mogu naknadno preuzeti profil, a potvrda organizatora o privoli bilježi se zasebno.",
