  "Review the complete row here. Runner identity and race assignment come from the registration record; timing and participant status are corrected below.": "Ovdje pregledaj cijeli redak. Identitet natjecatelja i dodijeljena utrka preuzimaju se iz zapisa prijave; vrijeme i status sudionika ispravljaju se u nastavku.",
