  "Test Race accepts up to 10 runners. This data never appears in the public race or real results.": "Probna utrka prihvaća do 10 natjecatelja. Ti se podaci nikada ne prikazuju u javnom utrci ni stvarnim rezultatima.",
  "Test runner added. Assign a bib at the Race Day desk.": "Probni natjecatelj je dodan. Dodijeli mu startni broj na pultu za dan utrke.",
  "This race has no configured checkpoint or finish field to edit. You can still correct the participant status below.": "Ova utrka nema postavljeno polje kontrolne točke ni cilja za uređivanje. U nastavku i dalje možeš ispraviti status sudionika.",
  "This records that the runner started but did not finish. It can be corrected later from temporary results.": "Time se bilježi da je natjecatelj startao, ali nije završio. Zapis se poslije može ispraviti iz privremenih rezultata.",
