  "42K / 21K / 10K": "42K / 21K / 10K",
  "A club qualifies with at least 1 eligible finisher. This sets the maximum number of its best finishing places included in the score.": "Klub se kvalificira s najmanje jednim prihvatljivim natjecateljem koji je završio utrku. Time se određuje najveći broj njegovih najboljih plasmana uključenih u bodovanje.",
  "A custom upload or pasted URL replaces the default image. The selected image is saved with the race.": "Vlastiti prijenos ili zalijepljena poveznica zamjenjuju zadanu sliku. Odabrana slika sprema se s utrkom.",
  "A fast coastal trail race above Skradin with forest shade, sea views, and a technical finish ridge back into the race village.": "Brza obalna trail utrka iznad Skradina, sa šumskim hladom, pogledom na more i tehnički zahtjevnim završnim grebenom prema središtu utrke.",
  "About Section": "Odjeljak O utrci",
  "Access notes, landmarks, parking instructions, shuttle details, or anything athletes and staff should know.": "Napomene o pristupu, znamenitosti, upute za parkiranje, pojedinosti prijevoza ili sve što natjecatelji i osoblje trebaju znati.",
  "Acknowledge every current publish blocker before publishing.": "Prije objave potvrdi svaku trenutačnu prepreku objavi.",
  "Active membership is checked when the athlete registers. Club roles never grant organizer access.": "Aktivno članstvo provjerava se pri prijavi natjecatelja. Klupske uloge nikada ne daju organizatorski pristup.",
