  "Assign a GPX route first. Physical route points come from the route. Race setup then decides which ones act as checkpoints, water or aid stations, marshal posts, medical support, and cutoff controls.": "Najprije dodijeli GPX rutu. Fizičke točke preuzimaju se sa rute. U postavljanju utrke zatim odredi koje služe kao kontrolne ili okrjepne postaje, mjesta s vodom, sudačka mjesta, medicinska podrška i kontrole vremenskog limita.",
  "Assign permanent team members to this race or create expiring roles for timers and other race-only work. Temporary roles and assignments stay inside this race.": "Dodijeli stalne članove ekipe ovom utrci ili izradi vremenski ograničene uloge za mjeritelje vremena i druge poslove samo na ovom utrci. Privremene uloge i zaduženja ostaju unutar ovog utrke.",
