  "Check to acknowledge this requirement and override it for this publish. The underlying setup remains unchanged.": "Označi da potvrdiš ovaj zahtjev i premostili ga za ovu objavu. Osnovne postavke ostaju nepromijenjene.",
  "Check-in, starts, and timing.": "Prijava na lokaciji, startovi i mjerenje vremena.",
  "Checking the current race publishing requirements.": "Provjera trenutačnih uvjeta za objavu utrke.",
  "Checkpoints, aid, timing and cutoffs. The saved route stays unchanged.": "Kontrolne točke, okrjepa, mjerenje vremena i vremenski limiti. Spremljena ruta ostaje nepromijenjena.",
  "Choose a button above to add a result category.": "Odaberi gumb iznad za dodavanje kategorije rezultata.",
  "Choose an image file.": "Odaberi slikovnu datoteku.",
