  "Choose one saved route before race setup. Distance, elevation, and route-adjacent race details prefill from the selected route.": "Prije postavljanja utrke odaberi jednu spremljenu rutu. Udaljenost, visinska razlika i povezane pojedinosti utrke unaprijed se popunjavaju iz odabrane rute.",
  "Choose the saved route used by this race.": "Odaberi spremljenu rutu koju koristi ova utrka.",
  "Choose the sex and age categories shown in this race's results.": "Odaberi spolne i dobne kategorije koje se prikazuju u rezultatima ove utrke.",
  "Click the map to pick coordinates for parking, start, finish, registration, info, weather, or medical points. You can also type a place / address and override coordinates manually.": "Klikni kartu da odabereš koordinate parkirališta, starta, cilja, prijave, informativne, meteorološke ili medicinske točke. Možeš i upisati mjesto/adresu te ručno promijeniti koordinate.",
  "Click the map, click the elevation profile, or enter a distance to snap to the nearest route point on the assigned route.": "Klikni kartu ili visinski profil ili unesi udaljenost za povezivanje s najbližom točkom dodijeljene rute.",
